class Solution {
public:
    int minCostConnectPoints(vector<vector<int>>& points) {
        int n = points.size();
        vector<int> minDist(n, 1e9);
        minDist[0] = 0;
        vector<bool> visited(n, false);
        int totalCost = 0;
        for (int step = 0; step < n; ++step) {
            int u = -1;
            for (int i = 0; i < n; ++i) {
                if (!visited[i] && (u == -1 || minDist[i] < minDist[u])) {
                    u = i;
                }
            }
            visited[u] = true;
            totalCost += minDist[u];
            int ux = points[u][0], uy = points[u][1];
            for (int v = 0; v < n; ++v) {
                if (!visited[v]) {
                    int dist = abs(ux - points[v][0]) + abs(uy - points[v][1]);
                    if (dist < minDist[v]) minDist[v] = dist;
                }
            }
        }
        return totalCost;
    }
};

